from rest_framework import viewsets, permissions
from rest_framework.decorators import action
from rest_framework.response import Response
from .models import WorkflowTemplate
from .serializers import WorkflowTemplateSerializer

class WorkflowTemplateViewSet(viewsets.ModelViewSet):
    serializer_class = WorkflowTemplateSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        return WorkflowTemplate.objects.filter(tenant=self.request.user.tenant)

    @action(detail=True, methods=["post"])
    def clone_template(self, request, pk=None):
        source_template = self.get_object()
        new_template = WorkflowTemplate.objects.create(
            tenant=request.user.tenant,
            name=f"Copy of {source_template.name}",
            definition=source_template.definition
        )
        return Response({"cloned_id": new_template.id, "source_id": source_template.id})
